class SyncService : Service() {
    private val scope = CoroutineScope(SupervisorJob() + Dispatchers.Default)

    override fun onStartCommand(intent: Intent?, flags: Int, startId: Int): Int {
        scope.launch {
            try {
                repo.sync()
            } finally {
                stopSelf(startId)      // stop THIS start, not the whole service
            }
        }
        return START_REDELIVER_INTENT
    }

    override fun onBind(intent: Intent): IBinder? = null

    override fun onDestroy() {
        scope.cancel()
        super.onDestroy()
    }
}

class NotesProvider : ContentProvider() {
    private val db by lazy { openDb(context!!) }   // lazy: not in onCreate

    override fun onCreate(): Boolean {
        // keep this fast — it runs on the main thread BEFORE Application.onCreate
        return true
    }

    override fun query(
        uri: Uri, projection: Array<String>?,
        selection: String?, selectionArgs: Array<String>?,
        sortOrder: String?,
    ): Cursor = db.query(uri, projection, selection, selectionArgs, sortOrder)

    override fun insert(uri: Uri, values: ContentValues?): Uri = db.insert(uri, values)
    override fun update(
        uri: Uri, values: ContentValues?,
        selection: String?, selectionArgs: Array<String>?,
    ): Int = db.update(uri, values, selection, selectionArgs)
    override fun delete(uri: Uri, selection: String?, selectionArgs: Array<String>?): Int =
        db.delete(uri, selection, selectionArgs)
    override fun getType(uri: Uri): String = MIME_DIR
}

class BootReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        if (intent.action != Intent.ACTION_BOOT_COMPLETED) return

        val pendingResult = goAsync()   // keep the process alive past onReceive
        scope.launch {
            try {
                workRepository.cleanupOldEntries()
            } finally {
                pendingResult.finish()  // must call, and within the timeout window
            }
        }
    }
}

class FeedFragment : Fragment(R.layout.feed) {
    private var _binding: FeedBinding? = null
    private val binding get() = _binding!!

    override fun onViewCreated(view: View, savedInstanceState: Bundle?) {
        _binding = FeedBinding.bind(view)

        // view-scoped: cancelled on onDestroyView, re-created on return
        viewLifecycleOwner.lifecycleScope.launch {
            viewLifecycleOwner.repeatOnLifecycle(Lifecycle.State.STARTED) {
                viewModel.items.collect { binding.list.submitList(it) }
            }
        }
    }

    override fun onDestroyView() {
        super.onDestroyView()
        _binding = null     // required — the Fragment outlives this view
    }
}

class ProfileViewModel(private val savedState: SavedStateHandle) : ViewModel() {
    // survives rotation AND process death (lives in the saved-state Bundle)
    val userId: String = checkNotNull(savedState["userId"])

    // process-scoped, re-read on restore
    val profile: StateFlow<Profile> = repo.observe(userId).stateIn(
        viewModelScope, SharingStarted.WhileSubscribed(5_000), Profile.Unknown
    )
}

// Config change = new Activity, same process. Statics, singletons and
// ViewModels survive. The Bundle and SavedStateHandle survive both events.

class EditorActivity : ComponentActivity() {
    private val dispatcher by lazy { onBackPressedDispatcher }

    private val dialogCallback = object : OnBackPressedCallback(true) {
        override fun handleOnBackPressed() {
            showDiscardDialog()      // intercept while dialog is showing
        }
    }

    fun openEditor() {
        // register LAST so this wins over the nav-controller callback
        dispatcher.addCallback(this, dialogCallback)
    }

    fun closeEditor() {
        dialogCallback.remove()      // must remove on exit
    }
}

class App : Application() {
    override fun onCreate() {
        super.onCreate()
        // critical path: crash handler, logger — nothing else
        crashlytics.init(this)

        // everything below can wait for the first frame
        val deferred = Handler(Looper.getMainLooper())
        deferred.post {
            analytics.init(this)
            featureFlags.refresh()
            imageLoader.warmCache()
        }
    }
}

// BAD — the incoming intent's flags and grants travel with it
fun onNewIntent(intent: Intent) {
    startActivity(intent)
}

// GOOD — copy only validated data into a fresh, grant-free intent
fun onNewIntent(intent: Intent) {
    val itemId = intent.getStringExtra("itemId")
        ?.takeIf { it.matches(Regex("[a-zA-Z0-9_-]{1,32}")) } ?: return
    startActivity(Intent(this, DetailActivity::class.java).apply {
        putExtra("itemId", itemId)
    })
}

class MainActivity : ComponentActivity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        enableEdgeToEdge()

        window.setDecorFitsSystemWindows(false)
        WindowCompat.getInsetsController(window, window.decorView)
            .show(SystemBars.NAVIGATION_BARS or SystemBars.STATUS_BARS)
        setContent { App() }
    }
}

// Track the window size class as a state the UI recomposes against
@Composable
fun rememberWindowSizeClass(): WindowSizeClass {
    val activity = LocalActivity.current
    val metrics = WindowMetricsCalculator.getOrCreate()
        .computeCurrentWindowMetrics(activity)
    return WindowSizeClass.calculateFromMetrics(metrics)
}
